// Generated by `just generate` from `src/kernel/state-events.ts`. Edit the source and run `just generate`.
// The format of `events.jsonl` in schema 2 and its reader.
// Each line after the header is one state change of a package or of a change.
// The reader takes a `FileReader`, so a test needs no file on disk.
// Schema 1 stays in `spec-store.ts` until the CLI switches to schema 2.

import path from "node:path";
import { SPEC_ROOT } from "./paths.ts";
import type { FileReader } from "./ports.ts";

/** The `schema` number of `events.jsonl` in schema 2. Another number stops the reader. */
export const SPEC_SCHEMA_2 = 2;

/** The `schema` key of the front matter of each Markdown file in schema 2. */
export const FRONT_SCHEMA_2 = "dotclaude-spec/2";

/** The name of the log file in the folder of a change. */
const EVENTS_FILE = "events.jsonl";

/**
 * One state change: a package that moved to `state`, or the change itself when `package` is absent.
 * The optional keys hold the evidence of the move: the commit `sha`, the `verify` result, the review `verdict`, the `findings`, the `decision`, the `note`, and the `model`.
 */
export type StateEvent = {
  readonly at: string;
  readonly package?: string;
  readonly state: string;
  readonly sha?: string;
  readonly verify?: { readonly command: string; readonly exit: number };
  readonly verdict?: "approve" | "reject";
  readonly findings?: readonly string[];
  readonly decision?: "fix-code" | "revise-spec";
  readonly note?: string;
  readonly model?: string;
};

/** The first line of `events.jsonl` in schema 2. */
export type EventsHeader2 = { readonly schema: typeof SPEC_SCHEMA_2 };

/** The path of `events.jsonl` of the change `id`. */
export const eventsPath2 = (id: string): string =>
  path.posix.join(SPEC_ROOT, id, EVENTS_FILE);

/** The header line of a new `events.jsonl` in schema 2, with its line end. */
export const eventsHeader2 = (): string =>
  `${JSON.stringify({ schema: SPEC_SCHEMA_2 } satisfies EventsHeader2)}\n`;

/** One line of `events.jsonl` for `event`, with its line end. */
export const eventLine2 = (event: StateEvent): string =>
  `${JSON.stringify(event)}\n`;

/** Parses one line of `file`, and names the file and the line when the line is not JSON. */
const parseLine = (file: string, line: number, text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`${file}:${line}: this line is not JSON.`);
  }
};

/** True when `text` is one JSON value. */
const isJson = (text: string): boolean => {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
};

/**
 * The state events of the change `id` and the line of a torn last line, or null when the change has no `events.jsonl`.
 * A torn last line has no line end and is not JSON, as a crash in the middle of an append leaves it.
 * The scan skips a torn last line and gives its line number in `torn`, or null when there is none.
 * The scan throws an `Error` that names the file when the header has a `schema` other than `SPEC_SCHEMA_2`.
 * It throws an `Error` that names the file and the line when a line that is not torn is not JSON.
 */
export const scanStateEvents = async (
  files: FileReader,
  id: string,
): Promise<{
  readonly events: readonly StateEvent[];
  readonly torn: number | null;
} | null> => {
  const file = eventsPath2(id);
  const text = await files.read(file);
  if (text === null) return null;
  const [head, ...rest] = text
    .split("\n")
    .map((raw, i) => ({ raw, line: i + 1 }))
    .filter(({ raw }) => raw.trim() !== "");
  const header = (
    head ? parseLine(file, head.line, head.raw) : {}
  ) as Partial<EventsHeader2>;
  if (header.schema !== SPEC_SCHEMA_2)
    throw new Error(
      `${file} has schema ${String(header.schema)}, which this version does not read.`,
    );
  const last = rest.at(-1);
  const open = !text.endsWith("\n");
  const events: StateEvent[] = [];
  for (const entry of rest) {
    if (entry === last && open && !isJson(entry.raw))
      return { events, torn: entry.line };
    events.push(parseLine(file, entry.line, entry.raw) as StateEvent);
  }
  return { events, torn: null };
};

/**
 * The state events of the change `id`, in the order of the log, or null when the change has no `events.jsonl`.
 * The reader skips a torn last line, as `scanStateEvents` does, and throws the errors of `scanStateEvents`.
 */
export const readStateEvents = async (
  files: FileReader,
  id: string,
): Promise<readonly StateEvent[] | null> =>
  (await scanStateEvents(files, id))?.events ?? null;
